Web Application Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(web_app_gateway, "Web Application Gateway") {
    Component(tls_termination, "TLS Termination Module", "NGINX", "Handles incoming HTTPS/TLS connections and decrypts traffic at the edge.")
    Component(reverse_proxy, "Reverse Proxy & Routing Engine", "NGINX", "Routes client requests to downstream core services and APIs.")
    Component(waf_module, "Rate Limiter & WAF Module", "NGINX Module", "Provides Web Application Firewall protection, rate limiting, and forwards security telemetry.")
    Component(jwt_filter, "JWT Validation Filter", "NGINX / Lua or Custom C Module", "Validates JSON Web Tokens (JWT) for incoming client requests.")
}

Rel(waf_module, audit_logging_sidecar, "Forwards security event telemetry", "Local IPC")

@enduml

Redis.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Redis container

System_Ext(Core_API_Service, "Core API Service", "Core API logic and Redlock execution.")
System_Ext(EMR_Engine, "EMR Engine", "High-performance EMR processing.")

Container_Boundary(Redis, "Redis") {
    Component(Redis_In_Memory_Cache, "Redis In-Memory Cache", "Redis Cluster v7.x", "Primary-replica caching and distributed locking for sub-second performance.")
    Component(Redis_JSON_RediSearch_Module, "Redis JSON & RediSearch Module", "Redis JSON / RediSearch", "In-memory indexing for fast EMR metadata retrieval.")
}

Rel(Core_API_Service, Redis_In_Memory_Cache, "Caches data and executes Redlock via ioredis", "TCP")
Rel(EMR_Engine, Redis_JSON_RediSearch_Module, "Caches EMR data and queries indexes via Redis JSON / RediSearch", "TCP")

@enduml
